-- Agent PRO — Phase 3 — RPCs (BACKEND.md, RPCs). All SECURITY DEFINER, search_path = '',
-- fully qualified names; execute revoked from public/anon/authenticated and granted per function.
--
-- Generated by *_catalog_sync.sql and called here at run time (plpgsql resolves names lazily):
--   public.catalog_interest_keys() returns text[]              -- submit_enquiry (active keys only)
--   public.catalog_interest_keys_all() returns text[]          -- publish_site (deprecated keys too)
--   public.catalog_premium_mode_months(p_mode text) returns int -- mark_premium_paid
--   public.catalog_reserved_slugs() returns text[]             -- is_reserved_slug
--   public.site_schema() returns jsonb                          -- publish_site
--
-- Error conventions for authenticated RPCs: raise with a snake_case message code and SQLSTATE
--   42501 not_authenticated / plan_read_only, P0002 not_found, 22023 invalid input, P0001 other.
-- Public (anon) RPCs never raise for user input; they return {ok:false, error:<code>}.

-- ===========================================================================
-- Private helpers
-- ===========================================================================

-- Reserved slugs come from shared/catalog.json (reservedSlugs) through the generated
-- public.catalog_reserved_slugs(). plpgsql so the name resolves at call time (catalog_sync runs later).
create or replace function private.is_reserved_slug(p_slug text)
returns boolean
language plpgsql
stable
set search_path = ''
as $$
begin
  return lower(p_slug) = any (coalesce(public.catalog_reserved_slugs(), '{}'::text[]));
end;
$$;

-- Reserved slugs are blocked on every write path, not just in is_slug_available().
-- SECURITY DEFINER because client writes fire it as `authenticated`, which has no usage on `private`.
create or replace function private.sites_slug_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if private.is_reserved_slug(new.slug) then
    raise exception 'slug_reserved' using errcode = '23514';
  end if;
  return new;
end;
$$;

create trigger sites_slug_guard
  before insert or update of slug on public.sites
  for each row execute function private.sites_slug_guard();

-- Indian mobile number -> '+91XXXXXXXXXX', or null if invalid.
create or replace function private.normalize_in_phone(p_phone text)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v text := regexp_replace(coalesce(p_phone, ''), '[[:space:]().-]', '', 'g');
begin
  if v ~ '^\+91[6-9][0-9]{9}$' then return v; end if;
  if v ~ '^91[6-9][0-9]{9}$' then return '+' || v; end if;
  if v ~ '^0[6-9][0-9]{9}$' then return '+91' || substr(v, 2); end if;
  if v ~ '^[6-9][0-9]{9}$' then return '+91' || v; end if;
  return null;
end;
$$;

create or replace function private.normalize_host(p_host text)
returns text
language sql
immutable
set search_path = ''
as $$
  select nullif(rtrim(split_part(lower(btrim(coalesce(p_host, ''))), ':', 1), '.'), '');
$$;

-- Resolve a published, servable site by slug (preferred when given) or by host.
-- Returns null if not found, unpublished, deleted, or the owner is lapsed.
create or replace function private.find_public_site(p_slug text, p_host text)
returns public.sites
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_site public.sites;
  v_slug text := nullif(lower(btrim(coalesce(p_slug, ''))), '');
  v_host text := private.normalize_host(p_host);
begin
  if v_slug is not null then
    select s.* into v_site from public.sites s where s.slug = v_slug;
  elsif v_host is not null then
    select s.* into v_site
      from public.site_domains d
      join public.sites s on s.id = d.site_id
     where d.hostname = v_host
       and d.deleted_at is null
       and d.status in ('active', 'renew_soon')
       and (d.expires_at is null or d.expires_at > now());
  end if;

  if v_site.id is null
     or v_site.deleted_at is not null
     or not v_site.is_published
     or v_site.published_content is null
     or public.entitlement(v_site.agent_id) = 'lapsed' then
    return null;
  end if;
  return v_site;
end;
$$;

-- The public payload: no private fields. agency_code only when the agent chose to show it.
create or replace function private.public_site_payload(p_site public.sites)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'template_key',      p_site.template_key,
    'accent',            p_site.accent,
    'locale',            p_site.locale,
    'published_content', p_site.published_content,
    'canonical_host', (
      select d.hostname from public.site_domains d
       where d.site_id = p_site.id and d.kind = 'custom' and d.deleted_at is null
         and d.status in ('active', 'renew_soon')
         and (d.expires_at is null or d.expires_at > now())
       order by (d.id is not distinct from p_site.primary_domain_id) desc, d.created_at
       limit 1),
    'profile', jsonb_build_object(
        'full_name',   p.full_name,
        'designation', p.designation,
        'city',        p.city,
        'photo_url',   p.photo_url,
        'phone',       p.phone)
      || case when p_site.published_content #> '{about,showAgencyCode}' = 'true'::jsonb
              then jsonb_build_object('agency_code', p.agency_code)
              else '{}'::jsonb end
  )
  from public.profiles p
  where p.id = p_site.agent_id;
$$;

-- Validate an object against a list of FieldSpecs from site-schema.json. Returns a jsonb array of
-- {section, field, item, rule} errors (item is the 0-based list index, or null).
create or replace function private.validate_fields(
  p_fields jsonb, p_obj jsonb, p_section text, p_item int, p_interests text[])
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  f        jsonb;
  v        jsonb;
  k        text;
  t        text;
  allowed  text[];
  elem     jsonb;
  i        int;
  errs     jsonb := '[]'::jsonb;
  is_empty boolean;
begin
  if jsonb_typeof(p_obj) is distinct from 'object' then
    p_obj := '{}'::jsonb;
  end if;

  for f in select * from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) loop
    k := f ->> 'key';
    t := f ->> 'type';
    v := p_obj -> k;
    is_empty := v is null
      or jsonb_typeof(v) = 'null'
      or (jsonb_typeof(v) = 'string' and btrim(v #>> '{}') = '')
      or (jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 0);

    if is_empty then
      if coalesce((f ->> 'required')::boolean, false) then
        errs := errs || jsonb_build_array(jsonb_build_object(
          'section', p_section, 'field', k, 'item', p_item, 'rule', 'required'));
      end if;
      continue;
    end if;

    -- allowed option keys for select / multiSelect
    allowed := null;
    if f ? 'options' then
      select array_agg(o ->> 'key') into allowed from jsonb_array_elements(f -> 'options') o;
    elsif f ->> 'optionsFrom' = 'catalog.interests' then
      allowed := p_interests;
    end if;

    if t in ('text', 'multiline', 'phone', 'email', 'url', 'image', 'date', 'swatch', 'select') then
      if jsonb_typeof(v) <> 'string' then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'type'));
        continue;
      end if;
      if f ? 'maxLength' and char_length(v #>> '{}') > (f ->> 'maxLength')::int then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'maxLength'));
      end if;
      if (t = 'phone' and private.normalize_in_phone(v #>> '{}') is null)
         or (t = 'email' and (v #>> '{}') !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$')
         or (t = 'url' and (v #>> '{}') !~* '^https?://[^[:space:]]+$') then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'format'));
      end if;
      if t = 'select' and allowed is not null and not ((v #>> '{}') = any (allowed)) then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'option'));
      end if;

    elsif t = 'number' then
      if jsonb_typeof(v) <> 'number' then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'type'));
      elsif (f ? 'min' and (v #>> '{}')::numeric < (f ->> 'min')::numeric)
         or (f ? 'max' and (v #>> '{}')::numeric > (f ->> 'max')::numeric) then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'range'));
      end if;

    elsif t = 'toggle' then
      if jsonb_typeof(v) <> 'boolean' then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'type'));
      end if;

    elsif t = 'multiSelect' then
      if jsonb_typeof(v) <> 'array' then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'type'));
      elsif allowed is not null and exists (
          select 1 from jsonb_array_elements(v) e
           where jsonb_typeof(e) <> 'string' or not ((e #>> '{}') = any (allowed))) then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'option'));
      end if;

    elsif t = 'list' then
      if jsonb_typeof(v) <> 'array' then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'type'));
        continue;
      end if;
      if f ? 'maxItems' and jsonb_array_length(v) > (f ->> 'maxItems')::int then
        errs := errs || jsonb_build_array(jsonb_build_object('section', p_section, 'field', k, 'item', p_item, 'rule', 'maxItems'));
      end if;
      i := 0;
      for elem in select * from jsonb_array_elements(v) loop
        errs := errs || private.validate_fields(f -> 'itemFields', elem, p_section, i, p_interests);
        i := i + 1;
      end loop;
    end if;
  end loop;
  return errs;
end;
$$;

-- Validate site content against public.site_schema(). Hidden sections are skipped unless pinned.
create or replace function private.validate_site_content(p_content jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_schema    jsonb := public.site_schema();
  -- Deprecated interests stay valid here so existing content still publishes; new website
  -- enquiries use the active-only catalog_interest_keys() (submit_enquiry).
  v_interests text[] := public.catalog_interest_keys_all();
  sec         jsonb;
  v_key       text;
  v_hidden    jsonb := case when jsonb_typeof(p_content -> 'hidden') = 'array' then p_content -> 'hidden' else '[]'::jsonb end;
  errs        jsonb := '[]'::jsonb;
begin
  if v_schema is null or jsonb_typeof(v_schema -> 'sections') <> 'array' then
    raise exception 'site_schema() is missing: apply the generated catalog_sync migration';
  end if;
  for sec in select * from jsonb_array_elements(v_schema -> 'sections') loop
    v_key := sec ->> 'key';
    if v_hidden ? v_key and not coalesce((sec ->> 'pinned')::boolean, false) then
      continue;
    end if;
    errs := errs || private.validate_fields(sec -> 'fields', p_content -> v_key, v_key, null, v_interests);
  end loop;
  return errs;
end;
$$;

create or replace function private.require_uid()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  v uuid := auth.uid();
begin
  if v is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;
  return v;
end;
$$;

create or replace function private.require_can_write()
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.can_write() then
    raise exception 'plan_read_only' using errcode = '42501';
  end if;
end;
$$;

-- ===========================================================================
-- Public (anon) RPCs
-- ===========================================================================

create or replace function public.get_public_site(slug text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_site public.sites := private.find_public_site(get_public_site.slug, null);
begin
  if v_site.id is null then
    return null;
  end if;
  return private.public_site_payload(v_site);
end;
$$;

create or replace function public.get_public_site_by_host(host text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_site public.sites := private.find_public_site(null, get_public_site_by_host.host);
begin
  if v_site.id is null then
    return null;
  end if;
  return private.public_site_payload(v_site);
end;
$$;

-- Website enquiry form. Order: resolve site (incl. lapse) -> honeypot -> validate -> rate limit -> insert.
create or replace function public.submit_enquiry(
  slug text, host text, name text, phone text, email text,
  interest text, message text, honeypot text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_site     public.sites := private.find_public_site(submit_enquiry.slug, submit_enquiry.host);
  v_honeypot text := btrim(coalesce(submit_enquiry.honeypot, ''));
  v_name     text := btrim(coalesce(submit_enquiry.name, ''));
  v_phone    text := private.normalize_in_phone(submit_enquiry.phone);
  v_email    text := nullif(lower(btrim(coalesce(submit_enquiry.email, ''))), '');
  v_interest text := nullif(btrim(coalesce(submit_enquiry.interest, '')), '');
  v_message  text := nullif(btrim(coalesce(submit_enquiry.message, '')), '');
  v_recent   int;
begin
  if v_site.id is null then
    return jsonb_build_object('ok', false, 'error', 'unavailable');
  end if;

  -- Honeypot filled: pretend success, store nothing.
  if v_honeypot <> '' then
    return jsonb_build_object('ok', true);
  end if;

  if char_length(v_name) < 1 or char_length(v_name) > 80 then
    return jsonb_build_object('ok', false, 'error', 'invalid', 'field', 'name');
  end if;
  if v_phone is null then
    return jsonb_build_object('ok', false, 'error', 'invalid', 'field', 'phone');
  end if;
  if v_email is not null and (char_length(v_email) > 120
      or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') then
    return jsonb_build_object('ok', false, 'error', 'invalid', 'field', 'email');
  end if;
  if v_interest is not null and not (v_interest = any (coalesce(public.catalog_interest_keys(), '{}'::text[]))) then
    return jsonb_build_object('ok', false, 'error', 'invalid', 'field', 'interest');
  end if;
  if v_message is not null and char_length(v_message) > 500 then
    return jsonb_build_object('ok', false, 'error', 'invalid', 'field', 'message');
  end if;

  -- At most 5 submissions per phone per site per rolling hour (soft-deleted rows still count).
  perform pg_advisory_xact_lock(hashtextextended(v_site.id::text || '|' || v_phone, 0));
  select count(*) into v_recent
    from public.enquiries e
   where e.site_id = v_site.id
     and e.phone = v_phone
     and e.source = 'website'
     and e.created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    return jsonb_build_object('ok', false, 'error', 'rate_limited');
  end if;

  insert into public.enquiries (agent_id, site_id, name, phone, email, interest, source, message, status)
  values (v_site.agent_id, v_site.id, v_name, v_phone, v_email, v_interest, 'website', v_message, 'new');

  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.record_site_view(slug text, host text)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_site public.sites := private.find_public_site(record_site_view.slug, record_site_view.host);
begin
  if v_site.id is null then
    return;
  end if;
  insert into public.site_daily_views as v (agent_id, site_id, day, views)
  values (v_site.agent_id, v_site.id, (now() at time zone 'Asia/Kolkata')::date, 1)
  on conflict (site_id, day) do update set views = v.views + 1;
end;
$$;

-- ===========================================================================
-- Authenticated RPCs
-- ===========================================================================

-- true when the slug has a valid format, isn't reserved, and isn't used by another agent's site.
create or replace function public.is_slug_available(slug text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid  uuid := private.require_uid();
  v_slug text := coalesce(is_slug_available.slug, '');
begin
  if v_slug !~ '^[a-z0-9-]{3,30}$' or private.is_reserved_slug(v_slug) then
    return false;
  end if;
  return not exists (
    select 1 from public.sites s where s.slug = v_slug and s.agent_id <> v_uid);
end;
$$;

-- Validate the draft against the schema; on success copy it to published.
-- Returns {ok:true, published_at} or {ok:false, errors:[{section, field, item, rule}]}.
create or replace function public.publish_site()
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid  uuid := private.require_uid();
  v_site public.sites;
  v_errs jsonb;
  v_now  timestamptz := now();
begin
  perform private.require_can_write();
  select s.* into v_site from public.sites s
   where s.agent_id = v_uid and s.deleted_at is null
   for update;
  if v_site.id is null then
    raise exception 'not_found' using errcode = 'P0002';
  end if;

  v_errs := private.validate_site_content(v_site.draft_content);
  if jsonb_array_length(v_errs) > 0 then
    return jsonb_build_object('ok', false, 'errors', v_errs);
  end if;

  update public.sites
     set published_content = draft_content,
         published_at = v_now,
         is_published = true
   where id = v_site.id;
  return jsonb_build_object('ok', true, 'published_at', v_now);
end;
$$;

-- Record a premium payment and advance next_due_date by the mode's months (from the catalog).
-- The new due date is anchored on start_date when the old due date lies on the start_date
-- schedule, so month-end dates don't drift (31 Jan -> 28/29 Feb -> 31 Mar).
create or replace function public.mark_premium_paid(policy_id uuid, amount numeric, paid_on date)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := private.require_uid();
  p_policy_id uuid := mark_premium_paid.policy_id;
  p_amount  numeric := mark_premium_paid.amount;
  p_paid_on date := mark_premium_paid.paid_on;
  v_policy  public.policies;
  v_months  int;
  v_elapsed int;
  v_next    date;
  v_id      uuid;
begin
  perform private.require_can_write();
  if p_amount is null or p_amount <= 0 then
    raise exception 'invalid_amount' using errcode = '22023';
  end if;
  if p_paid_on is null then
    raise exception 'invalid_paid_on' using errcode = '22023';
  end if;

  select p.* into v_policy from public.policies p
   where p.id = p_policy_id and p.agent_id = v_uid and p.deleted_at is null
   for update;
  if v_policy.id is null then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  if v_policy.next_due_date is null then
    raise exception 'no_due_date' using errcode = '22023';
  end if;

  v_months := public.catalog_premium_mode_months(v_policy.premium_mode);
  if v_months is null or v_months <= 0 then
    raise exception 'unknown_premium_mode' using errcode = '22023';
  end if;

  v_next := null;
  if v_policy.start_date is not null and v_policy.next_due_date >= v_policy.start_date then
    -- calendar-month difference (age() would give 0 months for 31 Jan -> 28 Feb)
    v_elapsed := ((extract(year from v_policy.next_due_date) - extract(year from v_policy.start_date)) * 12
                + (extract(month from v_policy.next_due_date) - extract(month from v_policy.start_date)))::int;
    if (v_policy.start_date + make_interval(months => v_elapsed))::date = v_policy.next_due_date then
      v_next := (v_policy.start_date + make_interval(months => v_elapsed + v_months))::date;
    end if;
  end if;
  if v_next is null then
    v_next := (v_policy.next_due_date + make_interval(months => v_months))::date;
  end if;

  insert into public.premium_payments (agent_id, policy_id, amount, paid_on, period_due_date)
  values (v_uid, v_policy.id, p_amount, p_paid_on, v_policy.next_due_date)
  returning id into v_id;

  update public.policies set next_due_date = v_next where id = v_policy.id;

  return jsonb_build_object(
    'payment_id', v_id, 'period_due_date', v_policy.next_due_date, 'next_due_date', v_next);
end;
$$;

-- Undo the most recent payment of a policy: soft-delete it (so sync sees the deletion) and restore
-- next_due_date from period_due_date. Only the latest live payment can be undone.
create or replace function public.undo_premium_payment(payment_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := private.require_uid();
  p_payment_id uuid := undo_premium_payment.payment_id;
  v_payment public.premium_payments;
  v_latest  uuid;
begin
  perform private.require_can_write();
  select pp.* into v_payment from public.premium_payments pp
   where pp.id = p_payment_id and pp.agent_id = v_uid and pp.deleted_at is null;
  if v_payment.id is null then
    raise exception 'not_found' using errcode = 'P0002';
  end if;

  perform 1 from public.policies p where p.id = v_payment.policy_id for update;

  select pp.id into v_latest from public.premium_payments pp
   where pp.policy_id = v_payment.policy_id and pp.deleted_at is null
   order by pp.period_due_date desc, pp.created_at desc
   limit 1;
  if v_latest <> v_payment.id then
    raise exception 'not_latest_payment' using errcode = 'P0001';
  end if;

  update public.premium_payments set deleted_at = now() where id = v_payment.id;
  update public.policies set next_due_date = v_payment.period_due_date where id = v_payment.policy_id;

  return jsonb_build_object('policy_id', v_payment.policy_id, 'next_due_date', v_payment.period_due_date);
end;
$$;

-- Delete the caller's account. Preconditions:
--   * no order in `paid` or `fulfilling` (raise orders_in_progress);
--   * no objects left in site-media/<uid>/ (raise media_not_deleted). Storage files must be removed
--     through the Storage API first (deleting storage.objects rows in SQL orphans the files).
-- Payment records are kept for tax: raw provider payloads are cleared, and orders/payments lose
-- agent_id through ON DELETE SET NULL. Everything else cascades from auth.users.
create or replace function public.delete_my_account()
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_uid();
begin
  if exists (select 1 from public.orders o
              where o.agent_id = v_uid and o.status in ('paid', 'fulfilling')) then
    raise exception 'orders_in_progress' using errcode = 'P0001';
  end if;
  if exists (select 1 from storage.objects so
              where so.bucket_id = 'site-media'
                and (storage.foldername(so.name))[1] = v_uid::text) then
    raise exception 'media_not_deleted' using errcode = 'P0001';
  end if;

  update public.payments set raw = null where agent_id = v_uid;
  delete from auth.users where id = v_uid;
end;
$$;

